from pathlib import Path
import json,re,html

root=Path(__file__).resolve().parents[3]
base=root/'muzei/literatura'
old=(base/'lit-slovo-o-polku-igoreve.html').read_text()
scenes=json.loads((Path(__file__).parent/'scenes.json').read_text())
if isinstance(scenes,dict):scenes=scenes.get('scenes',scenes.get('moments'))
esc=html.escape
hook=(Path(__file__).parent/'hero.txt').read_text().strip()
header=re.search(r'<header class="top">.*?</nav>',old,re.S).group(0)
audio_cfg=re.search(r'<script>window.MUSEUM_AUDIOGUIDE=.*?</script>',old,re.S).group(0)
audio_cfg=audio_cfg.replace("heading:'Плач Ярославны — услышать'","heading:'Услышать, как она ждала'")
audio_cfg=audio_cfg.replace("durationLabel:'около полутора минут'","durationLabel:'1 минута 35 секунд'")
audio_cfg=re.sub(r"lead:'[^']*'", "lead:'Она хочет долететь до мужа и обтереть его раны. Послушай её просьбу к ветру, реке и солнцу.'",audio_cfg)
audio_cfg=audio_cfg.replace("Перевод Василия Жуковского.","По переводу Василия Жуковского.")
audio_cfg=audio_cfg.replace("note:'Озвучено синтезом речи — временно, до записи голосом.'","note:'Синтезированное чтение. Адаптация перевода В. А. Жуковского; древнерусский текст доступен отдельно.'")

